"""Prepare a technical appendix and unfilled group review worksheet."""
from pathlib import Path
import html
import json
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'docs/application_20261026'
EV=ROOT/'docs/evidence/dot_04/application_20261026'
def esc(x):return html.escape(str(x))
def table(head,rows):return '<table><thead><tr>'+''.join(f'<th>{esc(h)}</th>' for h in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{esc(v)}</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table>'
def main():
    OUT.mkdir(parents=True,exist_ok=True)
    audit=json.loads((EV/'APPLICATION_AUDIT.json').read_text(encoding='utf-8'))
    cat=json.loads((ROOT/'demo/cases/catalog.json').read_text(encoding='utf-8'))
    pct=lambda x:'—' if x is None else f'{100*x:.2f}%'
    titles={x['id']:x['title'] for x in cat['cases']}
    example=[]
    for row in audit['checks']:
        if row['target_fpr']!=.05 or row['model'] not in ('RF','IF'):continue
        s=row['summary'];c=s['confusion'];example.append([titles[row['case']],row['model'],s['normal_support'] if s['labeled_rows'] else '—',s['attack_support'] if s['labeled_rows'] else '—',c['FP'] if s['labeled_rows'] else '—',c['FN'] if s['labeled_rows'] else '—',pct(s['fpr']),pct(s['recall'])])
    pages=[]
    citation_metadata=json.loads((EV/'PUBLISHER_CITATION_METADATA_20261026.json').read_text(encoding='utf-8'))
    pages.append('''<h1>Bổ sung demo ứng dụng NIDS</h1><p class="lead">Tài liệu kỹ thuật đi kèm bản thảo đợt 3, đợt 4 và báo cáo tổng. Phần bổ sung giúp quan sát một đường chạy từ dữ liệu đến dự đoán, giữ bằng chứng và tự ghi nhận xét.</p><p>Ngày chuẩn bị: 26/10/2026. Thành viên: Trịnh Trâm Anh, Hoàng Văn Vương Thu, Nguyễn Trọng Tín. Đây là bản chuẩn bị có công cụ hỗ trợ, chưa được nhóm nghiệm thu hoặc giảng viên duyệt.</p><h2>Phạm vi đã triển khai</h2><p>Ứng dụng chạy local tại <code>http://127.0.0.1:4397/lab</code>. Người xem chọn tình huống, một mô hình, scenario và target validation; ứng dụng kiểm CSV mẫu, gọi mô hình đã lưu, hiện dần từng bản ghi, đối chiếu nhãn nếu có rồi cho tải JSON/CSV. Giao diện không tự viết nhận xét của thành viên.</p><h2>Luồng xử lý</h2>'''+table(['Bước','Xử lý','Đầu ra'],[
        ['1','Chọn CSV mẫu; kiểm hash và schema','Các flow record đúng đầu vào'],['2','Transform bằng preprocessor đã fit','Ma trận feature đúng bundle'],['3','Gọi RF/XGB/IF/AE đã lưu','Score từng record'],['4','So score với ngưỡng Normal validation','Normal/Attack'],['5','Đối chiếu label nếu có','TP/FP/TN/FN và chỉ số có support'],['6','Người xem đánh dấu, ghi chú và tải file','Hồ sơ phiên với config/ID/kết quả']])+'''<h2>Quan hệ với nghiên cứu chính</h2><p>Giữ ba RQ, 80 run, năm seed và policy ngưỡng 1%/5%. Demo dùng bundle seed 42; các mẫu chỉ là lát cắt từ official test đã dùng trong nghiên cứu. Kết luận so sánh vẫn dựa toàn test và năm seed.</p><p class="note">Đây là phát lại flow, chưa phải lab phát sinh tấn công, cảm biến mạng hoặc IPS. Khoảng cách hiển thị không phải latency hay throughput của hệ thống. Nhãn attack_cat chỉ phục vụ đối chiếu; model trả Normal/Attack, chưa phân loại tên attack hoặc tự học mẫu mới.</p>''')
    p=cat['provenance']
    pages.append('''<h1>Nguồn dữ liệu và mã xử lý</h1><h2>Hồ sơ nguồn</h2><p>UNSW-NB15 có trang phát hành của UNSW và bài công bố của Nour Moustafa, Jill Slay tại MilCIS 2015. Trang UNSW mô tả dữ liệu được tạo trong Cyber Range Lab bằng IXIA PerfectStorm, gồm Normal và hành vi tấn công sinh trong lab. Hai CSV subset công bố có 175.341 và 82.332 dòng.</p><p><a href="https://research.unsw.edu.au/projects/unsw-nb15-dataset">Trang UNSW</a> · <a href="https://doi.org/10.1109/MilCIS.2015.7348942">DOI bài gốc</a>. Trang dataset được đối chiếu lại ngày 26/10; truy cập DOI hiện gặp trang kiểm tra trình duyệt, không ghi thành đọc lại toàn văn.</p><p>Manifest local khai báo trang UNSW và mirror Mireu-Lab trên Hugging Face. Chưa xác lập đường tải gốc chính xác hoặc đối chiếu byte với bản tải trực tiếp từ UNSW. SHA-256 nhận diện file local, chưa tự chứng minh nguồn tải.</p><p class="hash">Testing: '''+esc(p['source_sha256'])+'''</p><p>45 cột gồm 42 feature và id/label/attack_cat. Dữ liệu mất cân bằng; kiểm local có 8.541/82.332 test record trùng vector 42 feature với official train. Overlap với tập fit thực tế mỗi seed/model được phân tích riêng trong báo cáo chính.</p><h2>Đường đi tới hàm thật</h2>'''+table(['File trong src/nids_benchmark','Hàm chính và vai trò'],[
        ['data.py','make_development_split: loại held-out trước split'],['preprocessing.py','build_preprocessor / transform_frame: impute, scale, one-hot'],['models.py','fit_model / FittedModel.score: adapter RF/XGB/IF/AE'],['runner.py','run_experiment: nối toàn bộ pipeline và lưu artifact'],['evaluation.py','select_threshold / evaluate_test_scores: ngưỡng và metric'],['demo.py','predict_csv / predict_frame: suy luận trên bundle thật'],['application.py','load_case / run_case / summarize: nguồn mẫu và phiên demo']])+'''<p>Backend: <code>scripts/demo_server.py</code>, Python HTTP server trên loopback. Frontend: <code>demo/index.html</code> và <code>demo/lab.html</code>, HTML/CSS/JavaScript.</p><p class="note">Dataset, thuật toán và thư viện là phần kế thừa. Pipeline, protocol, kiểm dữ liệu, phân tích và ứng dụng là sản phẩm triển khai của dự án có công cụ hỗ trợ. Chưa có bằng chứng phát minh thuật toán mới hay cải thiện hiệu năng sau một thay đổi phương pháp. Đóng góp cá nhân cần ghi theo việc thực sự tự kiểm, sửa và giải thích.</p>''')
    pages.append('''<h1>Kết quả chạy các tình huống</h1><p>Bộ mẫu gồm tám tình huống. Chọn 20 ID nhỏ nhất mỗi nhóm Normal, Generic, Reconnaissance, DoS, Exploits. Bộ hỗn hợp lấy 10 dòng mỗi nhóm; hai tình huống kiểm ứng dụng lần lượt bỏ nhãn và bỏ dur. Không chọn dòng theo dự đoán đúng.</p><p>Bảng dưới là ví dụ RF/IF ở target validation 5%, seed 42; tình huống held-out dùng LR/LD/LE tương ứng, còn lại dùng CS. Dấu — nghĩa không có mẫu số. Đây là mô tả mẫu demo, không thay kết quả toàn test.</p>'''+table(['Tình huống','Model','Normal','Attack','FP','FN','FPR','Recall'],example)+'''<h2>Kiểm kỹ thuật</h2><p>Đã kiểm 46 unit test. Bộ demo mới có 56 tổ hợp hợp lệ, 1.600 dự đoán đối chiếu và tám lần từ chối CSV thiếu dur. Giá trị fixture truy về đúng 202 dòng, tính cả các bản lặp giữa các tình huống; đây không phải 202 mẫu độc lập.</p><p>Những nhãn dự đoán đối chiếu đều khớp baseline. Khi đổi batch size, AE float32 có sai khác score: lớn nhất tuyệt đối 0,000215810, ở score khoảng 296,987. Kiểm số dùng |s − s₀| ≤ 10⁻⁶ + 10⁻⁶|s₀| và vẫn yêu cầu nhãn khớp chính xác. Không diễn giải score là giống từng byte.</p><p>UI kiểm phát/tạm dừng, xuất phiên dở/hoàn tất, ghi chú, hàng đánh dấu, input không nhãn/sai cấu trúc, xóa kết quả cũ khi đổi cấu hình và 140 lượt bố cục trên năm cỡ màn hình. Sáu mục chuyển bằng nút; bảng và tài liệu chia trang, ghi chú giữ khi đổi mục. Bằng chứng gốc: <code>docs/evidence/dot_04/application_20261026/</code>.</p><p class="note">Các nhận xét về FPR/recall và lựa chọn model của nhóm để trống ở trang sau. Kết quả kiểm tự động không xác nhận mức hiểu, đóng góp hay đồng ý nộp của thành viên.</p>''')
    pages.append('''<h1>Phiếu nhóm tự chạy và nhận xét</h1><p>Điền sau khi tự thao tác. Có thể đính kèm JSON/CSV tải từ demo hoặc ghi trực tiếp vào bản chung. Các ô hiện chưa có xác nhận thành viên đã hoàn thành.</p>'''+table(['Thành viên','Việc cần tự đối chiếu','Ngày / file / điều muốn sửa'],[
        ['Anh','Nguồn UNSW, mirror, phiên bản CSV, một hàng support và giới hạn dữ liệu','Chưa điền'],['Thu','Một FP/FN; FPR và recall ở hai target; kết luận đúng mẫu số','Chưa điền'],['Tín','Một flow từ API tới transform/score/threshold; tự chạy và giữ log','Chưa điền']])+'''<h2>Thứ tự thử</h2><ol><li>Chỉ nguồn dữ liệu và giải thích 42 feature; mở một hàm code phụ trách xử lý.</li><li>Chạy Normal rồi Generic. Ghi model, target, support và lỗi quan sát.</li><li>Chạy Reconnaissance bằng LR, thử RF rồi IF. Giải thích vì sao gọi lớp này là held-out.</li><li>Giữ nguyên dữ liệu/model, đổi target 5% sang 1%. Tự nhận xét ngưỡng và kết quả.</li><li>Thử dữ liệu chưa nhãn, đánh dấu một dòng để kiểm; thử file thiếu dur.</li><li>Tải phiên, ghi điều hiểu và câu hỏi; một bạn khác đọc góp ý cụ thể.</li></ol><h2>Nhận xét của nhóm</h2><p>Điều quan sát được, có số liệu và ID/file đối chiếu:</p><div class="blank"></div><p>Giới hạn, điều chưa hiểu và thay đổi muốn thực hiện:</p><div class="blank"></div><p>Người đọc góp ý, ngày đọc và cách xử lý:</p><div class="blank short"></div><p class="note">AI được dùng như công cụ hỗ trợ chuẩn bị mã và hồ sơ. Thành viên tự kiểm chứng, diễn giải, sửa và chịu trách nhiệm về nội dung trình bày. Chưa bảo đảm điểm bonus hoặc đáp ứng rubric chưa được cung cấp; phần này bổ sung khả năng demo trong phạm vi đề tài hiện tại.</p>''')
    css='''@page{size:A4;margin:0}*{box-sizing:border-box}body{margin:0;color:#222;font:11pt/1.48 'Segoe UI',sans-serif;background:#e8ebed}.page{width:210mm;height:297mm;margin:12px auto;background:white;padding:15mm 17mm 17mm;position:relative;overflow:hidden}.body{height:260mm}h1{font-size:21pt;line-height:1.25;margin:0 0 14px}h2{font-size:13pt;margin:16px 0 7px}p{margin:8px 0}.lead{font-size:12pt}table{border-collapse:collapse;width:100%;font-size:9pt;margin:12px 0;line-height:1.35}td,th{border:1px solid #bbb;padding:6px;text-align:left;vertical-align:top}th{background:#eef1f4}code,.hash{font:9pt/1.4 Consolas,monospace;overflow-wrap:anywhere}.note{font-size:9pt;background:#f1f3f5;padding:10px;border-left:2px solid #8799a6}.foot{position:absolute;left:17mm;right:17mm;bottom:9mm;font-size:9pt;border-top:1px solid #ddd;padding-top:4px;display:flex;justify-content:space-between}.blank{height:21mm;border:1px solid #ccc}.short{height:16mm}li{margin:5px 0}a{color:#285a81}@media print{body{background:white}.page{margin:0;break-after:page}.page:last-child{break-after:auto}}@media(max-width:800px){.page{margin:0}}'''
    references=[]
    venues=[
        'MilCIS, 2015, tr. 1–6.',
        'Information Security Journal, 25(1–3), 2016, tr. 18–31.',
        'IEEE Transactions on Big Data, 5(4), 2019, tr. 481–494. Trang UNSW ghi 2017; tập/số bản in là 2019.',
        'Data Analytics and Decision Support for Cybersecurity, Springer, 2017, tr. 127–156.',
        'Big Data Technologies and Applications, Springer, 2021, tr. 117–135; hội nghị BDTA/WiCON 2020.'
    ]
    for paper,venue in zip(citation_metadata['papers'],venues,strict=True):
        references.append('<li>'+esc('; '.join(paper['authors']))+'. <em>'+esc(paper['title'])+'</em>. '+esc(venue)+' <a href="https://doi.org/'+esc(paper['doi'])+'">doi:'+esc(paper['doi'])+'</a>.</li>')
    pages.append('''<h1>Ghi nhận nguồn UNSW-NB15</h1><p>Trang phát hành UNSW đề nghị người sử dụng dataset dẫn năm công trình dưới đây. Hai bài đầu đã có trong báo cáo chính; trang này bổ sung đầy đủ thông tin ghi nhận nguồn cho bộ hồ sơ.</p><p><a href="https://research.unsw.edu.au/projects/unsw-nb15-dataset">research.unsw.edu.au/projects/unsw-nb15-dataset</a><br>Đối chiếu trang và thông tin xuất bản: 26/10/2026.</p><ol class="refs">'''+''.join(references)+'''</ol><h2>Phạm vi đã kiểm</h2><p class="source-note">Thông tin tác giả, tên bài, nơi xuất bản, năm, trang và DOI được đối chiếu metadata nhà xuất bản qua Crossref. Với bài 4–5, có đối chiếu trang tóm tắt Springer; bài 5 có thêm tóm tắt arXiv: <a href="https://arxiv.org/abs/2011.09144">2011.09144</a>. Đây không phải xác nhận đã đọc toàn văn ba nguồn bổ sung hoặc đã tái lập phương pháp của các bài đó.</p><p class="source-note">Bài NetFlow giới thiệu các biểu diễn khác, trong đó có NF-UNSW-NB15. Dự án hiện dùng hai CSV subset UNSW-NB15 gốc, 42 feature; không được gọi hai bản này là cùng một đầu vào.</p><h2>Điều còn cần xác minh về bản CSV</h2><p class="source-note">Link tải trên trang UNSW dẫn tới SharePoint và chuyển sang đăng nhập Microsoft khi truy cập ẩn danh. Chưa tải được CSV để đối chiếu từng byte. Hash trong hồ sơ xác định bản local; manifest khai báo cả UNSW và mirror Mireu-Lab, chưa chứng minh đường tải gốc chính xác.</p><p class="note">Trang này ghi nhận nguồn dataset, không phải bằng chứng cải tiến thuật toán hoặc điểm số đã được thầy chấp nhận. Anh, Thu và Tín cần tự mở các nguồn liên quan phần mình rồi ghi lại điều đã kiểm và điều còn chưa rõ.</p>''')
    css+=' .refs{font-size:9.5pt;line-height:1.4}.refs li{margin:10px 0}.refs a{overflow-wrap:anywhere}.source-note{font-size:10pt;line-height:1.4}'
    content='<!doctype html><html lang="vi"><meta charset="utf-8"><title>Bổ sung demo ứng dụng NIDS</title><style>'+css+'</style>'+''.join(f'<section class="page"><div class="body">{body}</div><footer class="foot"><span>TLCN · Bản bổ sung 26/10/2026 · Chờ nhóm tự rà soát</span><span>{i} / {len(pages)}</span></footer></section>' for i,body in enumerate(pages,1))+'</html>'
    (OUT/'report.html').write_text(content,encoding='utf-8')
    print(OUT/'report.html')
if __name__=='__main__':main()
